-- ============================================================================
-- B5 FOLLOW-ON W1 (grade integrity): gasprocessing.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 4 and
-- the annotations in docs/graded-field-audit/annot/gasprocessing.json. Owner
-- approved D1 to D7 as recommended, 2026-09-21.
--
-- BEGINNER
--   btexTonsYear graded the BTEX carried to the still overhead, a ppmv mole
--   balance the Associate tier never teaches (the worked lesson defers it to a
--   later tier), and the Suite prints it to one decimal against a 1e-5 tolerance
--   (B5 finding 1). The sixth field is now the reboiler duty, step six of the
--   beginner worked lesson: the daily circulation times the sensible heat plus
--   the water overhead per gallon with its reflux, over 24000000. The capstone
--   already stated the reflux ratio 0.22; the prompt now also states the 1100
--   Btu a pound water overhead, the module's own typed figure, so that
--   held-for-literature constant is a condition of the problem (as OTUMARA
--   states its 920 Btu a gallon) and the duty is reproducible by hand from the
--   prompt alone. The BTEX inputs no graded field uses are dropped from the
--   prompt. The key is tegReboilerMMBtuHr (the Professional tier already grades
--   an amine reboilerMMBtuHr, and the lab indexes the answer key by field key).
--   RE-KEY btexTonsYear (expected 38.678401618815194, tol 0.00001)
--       -> tegReboilerMMBtuHr 'Reboiler duty' MMBtu/hr, expected 0.7401512387317987, tol 1e-05
--   PROMPT was: The inlet carries 155 ppmv of BTEX, of which 0.12 is absorbed,
--   at a molecular weight of 92.
--   PROMPT now: Each pound of water the still boils off costs 1100 Btu of
--   overhead, the module's own figure, stated here so it is a condition of the
--   problem as well.
--   PROMPT was: and the BTEX that reaches the still overhead.
--   PROMPT now: and the reboiler duty, the sensible heat and the water overhead
--   with its reflux together, carried by that daily circulation.
--   PROMPT was: circulations in gpm and BTEX in short tons a year, to six
--   decimals.
--   PROMPT now: circulations in gpm and the duty in MMBtu an hour, to six
--   decimals.
--
-- WHAT DOES NOT MOVE. Every other field (key, label, unit, expected, tol and
-- position), the title, dataset, status and the row itself.
--
-- ATTEMPTS. Tiers whose graded key or tolerance moves: gasprocessing/beginner.
-- Before it writes, the file counts academy_capstone_attempts on each and
-- REFUSES if any exist, unless D5 allowlists that tier with the exact attempt
-- ids (allowlist: empty). Stored scores are never touched.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) and fields
-- (exact jsonb) as the post-20261023 scratch replay has them (it is
-- rewritten), OR its W1 form (left alone). Anything else raises and the whole
-- file rolls back. A file that will write first checks the round-off
-- post-state (20261023*) and refuses without it. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
begin
  -- gasprocessing / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'gasprocessing' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 gasprocessing refused: gasprocessing/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'b76462eec9718e1ddf5f9508fe9e9a17' and fields = '[{"key": "inletLbMMscf", "tol": 0.0001, "unit": "lb/MMscf", "label": "Saturated water content of the gas at the contactor inlet", "expected": 66.84513037385786}, {"key": "waterLbDay", "tol": 0.01, "unit": "lb/day", "label": "Water the unit takes out, the content difference applied to the rate", "expected": 2906.7211275713194}, {"key": "circGpm", "tol": 0.00001, "unit": "gpm", "label": "Glycol circulation, the stated ratio applied to that water rate", "expected": 7.266802818928299}, {"key": "circGpd", "tol": 0.01, "unit": "gal/day", "label": "The same glycol circulation as a daily volume", "expected": 10464.19605925675}, {"key": "sensiblePerGal", "tol": 0.0001, "unit": "Btu/gal", "label": "Sensible heat per gallon circulated, built from the stated glycol properties", "expected": 1324.7850000000003}, {"key": "btexTonsYear", "tol": 0.00001, "unit": "short tons/yr", "label": "BTEX carried to the still overhead", "expected": 38.678401618815194}]'::jsonb then 'old'
              when md5(prompt) = '2f278bcc95dd44cc8ef67fa4cf13dda2' and fields = '[{"key": "inletLbMMscf", "tol": 0.0001, "unit": "lb/MMscf", "label": "Saturated water content of the gas at the contactor inlet", "expected": 66.84513037385786}, {"key": "waterLbDay", "tol": 0.01, "unit": "lb/day", "label": "Water the unit takes out, the content difference applied to the rate", "expected": 2906.7211275713194}, {"key": "circGpm", "tol": 0.00001, "unit": "gpm", "label": "Glycol circulation, the stated ratio applied to that water rate", "expected": 7.266802818928299}, {"key": "circGpd", "tol": 0.01, "unit": "gal/day", "label": "The same glycol circulation as a daily volume", "expected": 10464.19605925675}, {"key": "sensiblePerGal", "tol": 0.0001, "unit": "Btu/gal", "label": "Sensible heat per gallon circulated, built from the stated glycol properties", "expected": 1324.7850000000003}, {"key": "tegReboilerMMBtuHr", "tol": 1e-05, "unit": "MMBtu/hr", "label": "Reboiler duty", "expected": 0.7401512387317987}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'gasprocessing' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 gasprocessing refused: gasprocessing/beginner matches neither its published form (prompt md5 b76462eec9718e1ddf5f9508fe9e9a17) nor its W1 form (prompt md5 2f278bcc95dd44cc8ef67fa4cf13dda2), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' then
    raise notice 'w1 gasprocessing: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 gasprocessing refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  -- ATTEMPTS. A tier whose graded key or tolerance this file moves must hold no
  -- capstone attempt (a stored score is never re-scored, but a learner could be
  -- graded differently on a retry of the same brief), unless D5 allowlists it
  -- with the exact attempt ids signed off. Any other attempt refuses.
  if v_s0 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'gasprocessing' and a.tier = 'beginner';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'gasprocessing/beginner' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'gasprocessing/beginner') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_extra) x;
          raise exception 'w1 gasprocessing refused: gasprocessing/beginner holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_idtxt;
        end if;
        raise notice 'w1 gasprocessing: gasprocessing/beginner holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_ids) x;
        raise exception 'w1 gasprocessing refused: gasprocessing/beginner holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_idtxt;
      end if;
    end if;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'IKOT ABASI, the TEG dehydration train on a gas gathering station making pipeline spec. The contactor takes 47 MMscfd at 880 psia and 109 degF and has to leave at 5 lb a MMscf. The circulation ratio chosen for this unit is 3.6 gallons of glycol per pound of water, and the lean glycol is 99.4 weight percent TEG. The absorber runs at 109 degF and the reboiler at 368 degF, with a reflux ratio of 0.22. The glycol has a heat capacity of 0.55 Btu per lb degF and weighs 9.3 lb a gallon, both stated, so they are conditions of the problem rather than lookups. Each pound of water the still boils off costs 1100 Btu of overhead, the module''s own figure, stated here so it is a condition of the problem as well. Report six values: the water the gas carries at the inlet, the water the unit takes out, the glycol circulation as a rate and as a daily volume, the sensible heat a gallon of that glycol costs, and the reboiler duty, the sensible heat and the water overhead with its reflux together, carried by that daily circulation. Water contents in lb a MMscf, circulations in gpm and the duty in MMBtu an hour, to six decimals. Daily masses in lb a day, daily volumes in gallons a day and heat in Btu a gallon, to four decimals.',
           fields = '[{"key": "inletLbMMscf", "tol": 0.0001, "unit": "lb/MMscf", "label": "Saturated water content of the gas at the contactor inlet", "expected": 66.84513037385786}, {"key": "waterLbDay", "tol": 0.01, "unit": "lb/day", "label": "Water the unit takes out, the content difference applied to the rate", "expected": 2906.7211275713194}, {"key": "circGpm", "tol": 0.00001, "unit": "gpm", "label": "Glycol circulation, the stated ratio applied to that water rate", "expected": 7.266802818928299}, {"key": "circGpd", "tol": 0.01, "unit": "gal/day", "label": "The same glycol circulation as a daily volume", "expected": 10464.19605925675}, {"key": "sensiblePerGal", "tol": 0.0001, "unit": "Btu/gal", "label": "Sensible heat per gallon circulated, built from the stated glycol properties", "expected": 1324.7850000000003}, {"key": "tegReboilerMMBtuHr", "tol": 1e-05, "unit": "MMBtu/hr", "label": "Reboiler duty", "expected": 0.7401512387317987}]'::jsonb
     where app_slug = 'gasprocessing' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 gasprocessing refused: gasprocessing/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '2f278bcc95dd44cc8ef67fa4cf13dda2' and fields = '[{"key": "inletLbMMscf", "tol": 0.0001, "unit": "lb/MMscf", "label": "Saturated water content of the gas at the contactor inlet", "expected": 66.84513037385786}, {"key": "waterLbDay", "tol": 0.01, "unit": "lb/day", "label": "Water the unit takes out, the content difference applied to the rate", "expected": 2906.7211275713194}, {"key": "circGpm", "tol": 0.00001, "unit": "gpm", "label": "Glycol circulation, the stated ratio applied to that water rate", "expected": 7.266802818928299}, {"key": "circGpd", "tol": 0.01, "unit": "gal/day", "label": "The same glycol circulation as a daily volume", "expected": 10464.19605925675}, {"key": "sensiblePerGal", "tol": 0.0001, "unit": "Btu/gal", "label": "Sensible heat per gallon circulated, built from the stated glycol properties", "expected": 1324.7850000000003}, {"key": "tegReboilerMMBtuHr", "tol": 1e-05, "unit": "MMBtu/hr", "label": "Reboiler duty", "expected": 0.7401512387317987}]'::jsonb) from public.academy_capstones where app_slug = 'gasprocessing' and tier = 'beginner' and active) is not true then
    raise exception 'w1 gasprocessing refused: gasprocessing/beginner does not read back as its W1 form';
  end if;

  raise notice 'w1 gasprocessing: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
